+/// reports to present the difference in a human-readable, source-located form.
+fn profdata_eq(a: &Path, b: &Path) -> Result<bool, AppError> {
+    let read = |p: &Path| {
+        std::fs::read(p).map_err(|e| format!("Failed to read profdata {} ({e})", p.display()))
